INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist PostgreSQL ausschließlich für relationale Datenbanken geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Unterstützt auch JSON und NoSQL-Features"}, {"text": "Ja", "correct": false, "because": "Bietet NoSQL-Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von PostgreSQL?', 3, '[{"text": "Hohe Skalierbarkeit", "correct": true, "because": "Bewältigt große Datenmengen"}, {"text": "Einfache Installation", "correct": false, "because": "Nicht primär"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Automatisierung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bietet PostgreSQL?', 5, '[{"text": "Transaktionssicherheit", "correct": true, "because": "Gewährleistet ACID"}, {"text": "Erweiterbare Datentypen", "correct": true, "because": "Unterstützt JSON, Arrays"}, {"text": "3D-Rendering", "correct": false, "because": "Nicht datenbankbezogen"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Andere Domäne"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PostgreSQL unterstützt MVCC. b) Es ist ausschließlich proprietär.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Open Source"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von PostgreSQL?', 4, '[{"text": "Sicherheitskonfiguration", "correct": false, "because": "Schützt Daten"}, {"text": "Performance-Optimierung", "correct": false, "because": "Verbessert Effizienz"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PostgreSQL für kleine Projekte geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Skalierbar für alle Größen"}, {"text": "Nein", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für PostgreSQL entscheidend?', 3, '[{"text": "ACID-Konformität", "correct": true, "because": "Sichert Datenintegrität"}, {"text": "Grafische Oberfläche", "correct": false, "because": "Nicht eingebaut"}, {"text": "Manuelle Dateneingabe", "correct": false, "because": "SQL automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Erweiterungen unterstützt PostgreSQL?', 5, '[{"text": "PostGIS", "correct": true, "because": "Für Geodaten"}, {"text": "PL/pgSQL", "correct": true, "because": "Für gespeicherte Prozeduren"}, {"text": "DirectX", "correct": false, "because": "Nicht datenbankbezogen"}, {"text": "Routerkonfiguration", "correct": false, "because": "Netzwerkdomäne"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) PostgreSQL unterstützt Replikation. b) Es ist nur für Windows. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist plattformübergreifend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für PostgreSQL?', 4, '[{"text": "SQL-Kenntnisse", "correct": false, "because": "Für Abfragen nötig"}, {"text": "Serverkonfiguration", "correct": false, "because": "Sichert Betrieb"}, {"text": "3D-Modellierungssoftware", "correct": true, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist PostgreSQL nur für relationale Daten?', 2, '[{"text": "Nein", "correct": true, "because": "Unterstützt JSON und mehr"}, {"text": "Ja", "correct": false, "because": "Bietet NoSQL-Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sicherheitsfunktionen bietet PostgreSQL?', 4, '[{"text": "Rollenbasierte Zugriffe", "correct": true, "because": "Schützen Daten"}, {"text": "SSL-Verschlüsselung", "correct": true, "because": "Sichert Übertragung"}, {"text": "Grafische Ausgabe", "correct": false, "because": "Kein Sicherheitsmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass PostgreSQL immer langsam ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Optimierung ermöglicht hohe Leistung"}, {"text": "Ja", "correct": false, "because": "Leistung konfigurierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung von PostgreSQL?', 3, '[{"text": "Indexoptimierung", "correct": true, "because": "Verbessert Abfragen"}, {"text": "Maximale Tabellenanzahl", "correct": false, "because": "Design wichtiger"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PostgreSQL unterstützt Trigger. b) Es benötigt immer eine GUI.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist CLI-basiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet PostgreSQL?', 5, '[{"text": "Open Source", "correct": true, "because": "Kostenfrei und anpassbar"}, {"text": "Erweiterbarkeit", "correct": true, "because": "Benutzerdefinierte Funktionen"}, {"text": "Clientseitige Logik", "correct": false, "because": "Serverbasiert"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei PostgreSQL unwichtig?', 3, '[{"text": "Backup-Strategien", "correct": false, "because": "Schützen Daten"}, {"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Wachstum"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Datenbankfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PostgreSQL für Echtzeitanwendungen geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Optimierung möglich"}, {"text": "Nein", "correct": false, "because": "Echtzeit machbar"}]'),
